    mediaThumbUrl: 'https://firebasestorage.googleapis.com/v0/b/masterproject-a832a.appspot.com/o/amsCurriculum%2Flessons%2F18036453.jpeg?alt=media&token=25f936bb-5092-5072-a9bc-f0fed82b3c53',
