    mediaThumbUrl: 'https://firebasestorage.googleapis.com/v0/b/masterproject-a832a.appspot.com/o/amsCurriculum%2Flessons%2F18036495.jpeg?alt=media&token=04fbda39-9467-5942-ad9e-709a47cc8555',
